:root{--mp-primary:#315d48;--mp-bg:#f4f6f4;--mp-text:#1d2922;--mp-muted:#68766d;--mp-border:#dce4de}*{box-sizing:border-box}body{margin:0;background:var(--mp-bg);color:var(--mp-text);font:15px Arial,sans-serif}.page{max-width:520px;margin:auto;padding:18px 16px 28px}.top{margin-bottom:16px}.store-name{font-size:12px;color:var(--mp-muted);font-weight:700;text-transform:uppercase;letter-spacing:.07em;margin-bottom:5px}h1{font-size:24px;margin:0}.card{background:#fff;border:1px solid var(--mp-border);border-radius:16px;padding:16px;margin:12px 0}.intro{color:var(--mp-muted);line-height:1.5;margin:8px 0 0}.field{margin:12px 0}.field label,.legend{display:block;font-weight:700;font-size:13px;margin-bottom:6px}.field input,.field textarea{width:100%;border:1px solid var(--mp-border);border-radius:10px;padding:12px;font:inherit;background:#fff}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.choices{display:flex;gap:8px;flex-wrap:wrap}.choices label{border:1px solid var(--mp-border);border-radius:20px;padding:9px 12px;font-size:13px}.choices input{accent-color:var(--mp-primary)}.mp-select{position:relative}.mp-select>button{width:100%;text-align:left;padding:12px;border:1px solid var(--mp-border);border-radius:10px;background:#fff;font:inherit}.mp-select-options{display:none;border:1px solid var(--mp-border);border-radius:10px;margin-top:5px;max-height:180px;overflow-y:auto;background:white}.mp-select.open .mp-select-options{display:block}.mp-select-options button{display:block;width:100%;border:0;background:#fff;text-align:left;padding:11px;font:inherit;border-bottom:1px solid #eef1ee}.primary{display:block;width:100%;border:0;border-radius:11px;padding:14px;background:var(--mp-primary);color:#fff;font-size:15px;font-weight:700}.error{padding:12px;background:#fff0ed;color:#a03120;border-radius:10px}.success{text-align:center;padding:24px 8px}.success i{font-size:40px;color:var(--mp-primary)}.help{font-size:12px;color:var(--mp-muted);line-height:1.5}.screen-title